argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$data='E:\WebAIBridge\app\data';
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$head=((@(& $git -C $repo rev-parse HEAD) -join '').Trim());
$branch=((@(& $git -C $repo branch --show-current) -join '').Trim());
$dirty=@(& $git -C $repo status --porcelain);
function ReadObj([string]$name){
  $p=Join-Path $data $name;
  if(!(Test-Path -LiteralPath $p)){return $null}
  try{return Get-Content -LiteralPath $p -Raw | ConvertFrom-Json}catch{return $null}
}
$r42=ReadObj 'projects-live-control-plane-cutover-r42.json';
$r41=ReadObj 'projects-live-control-plane-r41.json';
$state=ReadObj 'state.json';
$sup=ReadObj 'supervisor-watchdog.json';
$rec=ReadObj 'projects-live-control-plane-cutover-r42-reconcile.json';
$backs=@();
$br=Join-Path $data 'backups';
if(Test-Path $br){$backs=@(Get-ChildItem $br -Directory -Filter 'r42-cutover-*' | Sort-Object LastWriteTime -Descending | Select-Object -First 3 -ExpandProperty Name)}
[pscustomobject]@{
 head=$head;branch=$branch;detached=[string]::IsNullOrWhiteSpace($branch);dirtyCount=$dirty.Count;
 r42Exists=($null-ne$r42);r42Status=[string]$r42.status;r42Hold=$r42.holdActive;r42Target=[string]$r42.targetSha;
 r41Object=[string]$r41.object;
 lifecycleMode=[string]$state.operatorLifecycle.mode;queuePaused=$state.settings.paused;
 supervisorEnabled=$sup.enabled;supervisorMode=[string]$sup.mode;allowAutonomousSend=$sup.allowAutonomousSend;
 enforceHighMode=$sup.enforceHighMode;highModeStrategy=[string]$sup.highModeStrategy;migrationEnabled=$sup.migrationEnabled;
 reconcileExists=($null-ne$rec);reconcileStatus=[string]$rec.status;
 backups=$backs
}|ConvertTo-Json -Depth 4 -Compress
